#include <string.h>

char* concat(const char *a, const char *b) {
    // 两段长度相加 +1，未检查溢出
    size_t len = strlen(a) + strlen(b) + 1;
    char *buf = (char *)malloc(len);
    if (buf == NULL) return NULL;
    memcpy(buf, a, strlen(a));
    memcpy(buf + strlen(a), b, strlen(b));
    buf[len - 1] = '\0';
    return buf;
}

