from ldap3 import Server, Connection, ALL
from flask import Flask, request, jsonify

app = Flask(__name__)

# LDAP server configuration
LDAP_SERVER = "ldap://localhost:389"
BASE_DN = "dc=example,dc=com"
ADMIN_DN = "cn=admin,dc=example,dc=com"
ADMIN_PASSWORD = "secret123"

def get_ldap_connection():
    """Establish LDAP connection with admin credentials"""
    server = Server(LDAP_SERVER, get_info=ALL)
    conn = Connection(server, ADMIN_DN, ADMIN_PASSWORD, auto_bind=True)
    return conn

def sanitize_input(user_input):
    """Attempt to sanitize LDAP special characters - incomplete"""
    # Only replaces parentheses, but misses backslash and null byte
    return user_input.replace("(", "").replace(")", "")

@app.route('/api/search', methods=['GET'])
def search_users():
    """Search users by username - vulnerable endpoint"""
    username = request.args.get('username', '')

    # First sanitization attempt - only strips parentheses
    sanitized_username = sanitize_input(username)

    # Build LDAP filter using format string - vulnerable to injection
    filter_str = f"(uid={sanitized_username})"

    try:
        conn = get_ldap_connection()

        # Search with the constructed filter
        conn.search(
            search_base=BASE_DN,
            search_filter=filter_str,
            attributes=['uid', 'cn', 'mail'],
            search_scope=ldap3.SUBTREE
        )

        results = []
        for entry in conn.entries:
            results.append({
                'uid': str(entry.uid.value),
                'cn': str(entry.cn.value),
                'mail': str(entry.mail.value) if entry.mail else ''
            })

        conn.unbind()
        return jsonify({'status': 'success', 'data': results})

    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 500

@app.route('/health', methods=['GET'])
def health_check():
    """Health check endpoint"""
    return jsonify({'status': 'ok'})

